he pattern for the monthly data\n# I need to trace through each row and track the current year\n\n# First, let's find where each year block starts and what columns it uses\n# Looking at the structure:\n# After 1957 header, we have Jan-Dec 1957 in columns 1-3\n# But then it continues with 1959 in columns 4-6 and 1961 in 7-9\n\n# Let me trace through more carefully by looking at row patterns\nlines = content.split('<tr>')\n\n# Find indices with year markers\nyear_row_indices = []\nfor i, line in enumerate(lines):\n    if re.match(r'<td colspan=\"9\">\\d{4}</td>', line):\n        year_row_indices.append((i, re.search(r'(\\d{4})', line).group(1)))\n\nprint(\"\\nYear markers at row indices:\", year_row_indices)\n\n# Now let me trace through the rows between year markers to understand the mapping\nfor idx, (row_idx, year) in enumerate(year_row_indices):\n    print(f\"\\n=== Year {year} starting at row {row_idx} ===\")\n    # Print next few rows\n    for i in range(row_idx+1, min(row_idx+15, len(lines))):\n        if '<td>' in lines[i]:\n            # Extract month\n            month_match = re.search(r'<td>(January|February|March|April|May|June|July|August|September|October|November|December)</td>', lines[i])\n            if month_match:\n                print(f\"Row {i}: {month_match.group(1)}\")\n                # Get the values\n                values = re.findall(r'<td>(\\d+\\.\\d+|\\d+\\.\\d+ \\d+/)', lines[i])\n                print(f\"  Values: {values}\")\n                if month_match.group(1) == 'June':\n                    # Print full row for June\n                    print(f\"  FULL: {lines[i][:200]}\")\n                    break\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
